TESTDATA["pet2-t2"] = {"title": "Cambridge PET 2 · Test 2", "format": "2010", "reading": [{"part": 1, "items": [{"n": 1, "text": "LUGGAGE CANNOT BE REMOVED WITHOUT A RECEIPT", "img": "data:image/jpeg;base64,", "q": "", "options": ["You must show a receipt if you want to remove luggage.", "When you remove your luggage you are given a receipt.", "You can leave your luggage here without charge."], "answer": "A"}, {"n": 2, "text": "Anna,\nJeff rang: suggests taking a blanket (cold there!) No need to bring programme now. He’ll meet you at the festival entrance with your ticket.", "img": "data:image/jpeg;base64,", "q": "For the festival, Anna should bring", "options": ["her ticket.", "a blanket.", "the programme."], "answer": "B"}, {"n": 3, "text": "Will the last person to leave please switch off the lights", "img": "data:image/jpeg;base64,", "q": "", "options": ["Don’t turn the lights on until it’s necessary.", "Switch the lights on when you’re in the room.", "Don’t leave the lights on if the room is empty."], "answer": "C"}, {"n": 4, "text": "Has anyone seen my gold chain? I took it off before athletics. It’s a present from my boyfriend – he mustn’t find out it’s lost!\nSally", "img": "data:image/jpeg;base64,", "q": "", "options": ["Sally has given a chain to someone as a present.", "Sally’s boyfriend knows about the missing chain.", "Sally lost her chain when she got changed for sport."], "answer": "C"}, {"n": 5, "text": "Assistants needed because of new opening hours – apply inside", "img": "data:image/jpeg;base64,", "q": "This shop", "options": ["has just opened and jobs are available.", "is opening for longer and needs extra staff.", "will open late because of job interviews."], "answer": "B"}]}, {"part": 2, "people": [{"n": 6, "name": "Robert", "text": "Robert is planning to travel round the world by train. He would like a book with pictures and maps to take with him on his long journeys.", "answer": "D"}, {"n": 7, "name": "Mrs Jones", "text": "Mrs Jones used to love visiting France, but now she is too old to travel. She wants a book with lots of photographs which will help her to remember everything she enjoyed.", "answer": "G"}, {"n": 8, "name": "The Harpers", "text": "The Harpers are planning to go on holiday round Europe. They intend to drive their car and go for walks, so they need a book with maps and pictures to guide them on their way.", "answer": "F"}, {"n": 9, "name": "Clive", "text": "Clive wants to buy a book as a present for his friend Tom. Tom enjoys fishing and driving round England.", "answer": "B"}, {"n": 10, "name": "Peter", "text": "Peter has to write something for his history teacher about world explorers. He wants to know about explorers from the past and their travels to different parts of the world.", "answer": "C"}], "texts": [{"letter": "A", "title": "Allan Jowett — Jowett’s Railway Centres: Volume 1", "text": "Packed with information about 20 British railway centres, this wonderful book is handwritten and illustrated throughout with clear hand-drawn maps – a ‘true collector’s’ piece for those who are interested in railways."}, {"letter": "B", "title": "Alan Titchmarsh — The English River", "text": "Alan Titchmarsh explores 18 rivers, telling their interesting stories with an appreciation of them. A sailing from a past age introduces each chapter as his exploration moves across the English countryside."}, {"letter": "C", "title": "Robin Hanbury-Tenison — The Oxford Book of Exploration", "text": "This is a collection of the writing of explorers through the centuries. It describes the feelings and experiences of these brave adventurers who changed the world through their search for new lands."}, {"letter": "D", "title": "The Travel Club — Train Journeys of the World", "text": "First-hand accounts of 30 of the world’s most beautiful and dramatic railway journeys are found together with specially drawn maps and wonderful photographs that show the people and places on the route."}, {"letter": "E", "title": "Bruce Chatwin — Photographs and Notebooks", "text": "On all his travels, Bruce Chatwin took thousands of photographs and kept daily notebooks. Published here for the first time, the photographs are excellent, the notebooks both scholarly and funny. Will give great pleasure."}, {"letter": "F", "title": "Automobile Association — Walks and Tours in France", "text": "Explore spectacular and pretty France with 61 expertly researched motor tours and 114 walks, complete with route directions, super mapping, and descriptions and pictures of places of interest for the traveller."}, {"letter": "G", "title": "Shirley Pike — The Book of French Life", "text": "This beautiful volume contains forty wonderful photographs that show the very nature of French life – the perfect gift for anyone who finds this country as wonderful as Shirley Pike does."}, {"letter": "H", "title": "Ranulph Fiennes — Mind over Matter", "text": "The epic crossing of the Antarctic continent. The amazing story of his recent crossing of the Antarctic continent with another explorer, in which both showed great strength and courage."}]}, {"part": 3, "title": "A JOURNEY ALONG THE BEAUTIFUL DOURO RIVER", "text": "A JOURNEY ALONG THE BEAUTIFUL DOURO RIVER\n7 nights from £1050\n\nVOYAGES JULES VERNE operate a ‘hotel ship’ along the Douro river in Portugal. The MV Lady Ivy May can take 160 guests in double cabins, all of which face outside and have a private shower and WC. On board the ship, which has air-conditioning, you will find a sun-deck, lounge, bar, dining room, shop and library facilities.\n\nItinerary\nDay 1 Depart in the early evening from London Heathrow for Oporto. Your guide will meet you on arrival and take you to the Lady Ivy May, where you will spend the night.\nDay 2 After a morning’s sightseeing in Oporto, you will return to the ship and depart for Entre-os-Rios. This part of the journey up the river takes four hours.\nDay 3 You will continue travelling up the river. In the early evening, the ship stops at Pêso da Régua, where port wine is produced. At dinner you will be able to try the delicious food and drink from this area.\nDay 4 After breakfast you will travel south by bus to the ancient town of Lamego and visit the cathedral, several churches and a museum. The museum was formerly a palace and now has an excellent collection of paintings, tapestries and sculptures. You will then return to the ship and sail on to Tua.\nDay 5 At this point the Douro becomes very narrow. Depending on the depth of the river at the time, you may be able to continue by a smaller boat to the Spanish frontier at Barca d’Alva. The return journey to Tua is by coach and there is much to see along the way.\nDay 6 In the morning you will drive to São João da Pesqueira for one of the most wonderful views in the whole of the Douro valley. You will return to the ship for lunch and then join the Douro river valley railway for a beautiful ride through the countryside to Régua, where the Lady Ivy May will be waiting for you.\nDay 7 There will be a trip to Vila Real before returning to the ship for lunch and then setting off down the river to Oporto. You will sleep on board the Lady Ivy May.\nDay 8 You will arrive in Oporto in plenty of time for independent sightseeing and last-minute shopping, before you catch the flight home to London Heathrow.\n\nDeparture dates and prices (all prices are per person)\nJune 5, 12, 19, 26 £1100\nJuly 3, 10, 17, 24, 31 £1050\nAugust 7, 14, 21, 28 £1050\nSeptember 4, 11, 18, 25 £1100\n\nPrices include: return flights, 7 nights’ accommodation on board the Lady Ivy May with all meals, excursions and guides.\nNot included: travel insurance, tips.", "items": [{"n": 11, "q": "Each cabin on the Lady Ivy May is for two people.", "answer": "A"}, {"n": 12, "q": "You can borrow books on board the ship.", "answer": "A"}, {"n": 13, "q": "On arrival at Oporto, guests find their own way to the ship.", "answer": "B"}, {"n": 14, "q": "You spend a day looking round Oporto.", "answer": "B"}, {"n": 15, "q": "It takes a day to travel from Oporto to Entre-os-Rios.", "answer": "B"}, {"n": 16, "q": "The museum at Lamego used to be a palace.", "answer": "A"}, {"n": 17, "q": "It is sometimes possible for the Lady Ivy May to sail to the Spanish border.", "answer": "B"}, {"n": 18, "q": "The trip includes some travel by train.", "answer": "A"}, {"n": 19, "q": "You arrive back in Oporto on the day before your return flight.", "answer": "B"}, {"n": 20, "q": "Voyages Jules Verne arrange your travel insurance.", "answer": "B"}]}, {"part": 4, "title": "Winter Driving", "text": "Winter is dangerous because it’s so difficult to know what is going to happen and accidents take place so easily. Fog can be waiting to meet you over the top of a hill. Ice might be hiding beneath the melting snow, waiting to send you off the road. The car coming towards you may suddenly slide across the road.\n\nRule Number One for driving on icy roads is to drive smoothly. Uneven movements can make a car suddenly very difficult to control. So every time you either turn the wheel, touch the brakes or increase your speed, you must be as gentle and slow as possible. Imagine you are driving with a full cup of hot coffee on the seat next to you. Drive so that you wouldn’t spill it.\n\nRule Number Two is to pay attention to what might happen. The more ice there is, the further down the road you have to look. Test how long it takes to stop by gently braking. Remember that you may be driving more quickly than you think. In general, allow double your normal stopping distance when the road is wet, three times this distance on snow, and even more on ice. Try to stay in control of your car at all times and you will avoid trouble.", "items": [{"n": 21, "q": "What is the writer trying to do in the text?", "options": ["complain about bad winter driving", "give information about winter weather", "warn people against driving in winter", "advise people about safe driving in winter"], "answer": "D"}, {"n": 22, "q": "Why would somebody read this text?", "options": ["to find out about the weather", "for information on driving lessons", "to learn about better driving", "to decide when to travel"], "answer": "C"}, {"n": 23, "q": "What does the writer think?", "options": ["People should avoid driving in the snow.", "Drivers should expect problems in winter.", "People drive too fast in winter.", "Winter drivers should use their brakes less."], "answer": "B"}, {"n": 24, "q": "Why does the writer talk about a cup of coffee?", "options": ["to explain the importance of smooth movements", "because he thinks refreshments are important for drivers", "because he wants drivers to be more relaxed", "to show how it can be spilled"], "answer": "A"}, {"n": 25, "q": "Which traffic sign shows the main idea of the text?", "options": ["DRIVE CAREFULLY / ICE ON ROAD AHEAD", "REDUCE SPEED NOW / FOG AHEAD", "DRIVE CAREFULLY / ROAD REPAIRS AHEAD", "SLOW DOWN / ACCIDENT AHEAD"], "answer": "A"}]}, {"part": 5, "title": "SAMUEL PEPYS", "text": "The most famous diary (0) ……… (in) English was written by Samuel Pepys. It gives a detailed and interesting [26] of everyday life in England [27] 1660 and 1669. Pepys writes about important news stories of the time, like disease, an enemy navy [28] up the River Thames and the Great Fire of London.\nHe also writes about himself, even about his [29] – he can sleep during church or [30] at the pretty girls. He describes his home life – a [31] with his wife and how they became friends again, his worry about her illness. As well as books, he liked music, the theatre, card [32] and parties with good food and [33] of fun. Pepys was a busy man who had many important [34] – he was a Member of Parliament and President of the Royal Society. He is also [35] for his work for the British Navy.", "gaps": {"26": {"options": ["description", "letter", "notice", "story"], "answer": "A"}, "27": {"options": ["between", "from", "through", "to"], "answer": "A"}, "28": {"options": ["driving", "flying", "running", "sailing"], "answer": "D"}, "29": {"options": ["accidents", "plans", "dreams", "faults"], "answer": "D"}, "30": {"options": ["looked", "played", "talked", "thought"], "answer": "A"}, "31": {"options": ["conversation", "discussion", "quarrel", "talk"], "answer": "C"}, "32": {"options": ["battles", "games", "matches", "plays"], "answer": "B"}, "33": {"options": ["amount", "plenty", "much", "some"], "answer": "B"}, "34": {"options": ["acts", "hobbies", "jobs", "studies"], "answer": "C"}, "35": {"options": ["reviewed", "remembered", "reminded", "reported"], "answer": "B"}}}], "writing": [{"part": 1, "title": "Here are some sentences about going to the supermarket. Complete the second sentence so that it means the same as the first, using no more than three words.", "items": [{"n": 1, "first": "When she has to walk to the supermarket she finds it tiring.", "before": "She gets", "after": "when she has to walk to the supermarket.", "answers": ["tired"]}, {"n": 2, "first": "She is often driven to the supermarket by her neighbour.", "before": "Her neighbour often", "after": "a lift to the supermarket.", "answers": ["gives her"]}, {"n": 3, "first": "There are many types of coffee there.", "before": "You can buy a", "after": "types of coffee there.", "answers": ["lot of", "variety of", "range of"]}, {"n": 4, "first": "She asked an assistant how much the Colombian coffee cost.", "before": "She asked: ‘How", "after": "the Colombian coffee cost?’", "answers": ["much does"]}, {"n": 5, "first": "The Colombian coffee cost less than the Kenyan coffee.", "before": "The Colombian coffee wasn’t", "after": "as the Kenyan coffee.", "answers": ["as expensive", "so expensive", "as dear", "so dear"]}]}, {"part": 2, "items": [{"n": 6, "kind": "message", "task": "You have just had a wonderful holiday staying with some English-speaking friends in the countryside.\n\nWrite an e-mail to your friends. In your e-mail, you should\n• thank them for your stay\n• say what you most enjoyed about the countryside\n• suggest where you could meet each other next time.\n\nWrite 35–45 words on your answer sheet.", "points": ["ringraziare per l'ospitalità", "dire che cosa gli/le è piaciuto di più della campagna", "proporre dove vedersi la prossima volta"]}]}, {"part": 3, "items": [{"n": 7, "kind": "letter", "task": "This is part of a letter you receive from your penfriend:\n\n‘In your next letter, could you give me some advice? Tell me how you keep fit and healthy!’\n\nNow write a letter to your penfriend.\nWrite your letter in about 100 words on your answer sheet."}, {"n": 8, "kind": "story", "task": "You have to write a story for your English homework.\nYour story must have this title:\n\nAn exciting adventure\n\nWrite your story in about 100 words on your answer sheet."}]}], "listening": [{"part": 1, "audio": "audio/pet2-t2-l1.mp3", "items": [{"n": 1, "q": "When and where are they meeting?", "img": "data:image/jpeg;base64,", "options": ["", "", ""], "answer": "C"}, {"n": 2, "q": "What will Chris get for his birthday?", "img": "data:image/jpeg;base64,", "options": ["", "", ""], "answer": "C"}, {"n": 3, "q": "What does Mr Jones look like?", "img": "data:image/jpeg;base64,", "options": ["", "", ""], "answer": "C"}, {"n": 4, "q": "Where is he going to plant the tree?", "img": "data:image/jpeg;base64,", "options": ["", "", ""], "answer": "A"}, {"n": 5, "q": "What is the man going to buy?", "img": "data:image/jpeg;base64,", "options": ["", "", ""], "answer": "C"}, {"n": 6, "q": "Which is Gary’s room?", "img": "data:image/jpeg;base64,", "options": ["", "", ""], "answer": "A"}, {"n": 7, "q": "Which is the best vehicle for the man?", "img": "data:image/jpeg;base64,", "options": ["", "", ""], "answer": "A"}]}, {"part": 2, "intro": "You will hear a recorded message about an arts festival.", "audio": "audio/pet2-t2-l2.mp3", "items": [{"n": 8, "q": "The festival takes place from", "options": ["12 to 18 May.", "12 to 20 May.", "12 to 28 May."], "answer": "C"}, {"n": 9, "q": "What is on at the Theatre Royal on 19 May?", "options": ["jazz", "opera", "classical music"], "answer": "B"}, {"n": 10, "q": "During lunchtime jazz concerts at the Corn Exchange they sell", "options": ["soft drinks and sandwiches.", "wine and sandwiches.", "soft drinks and light meals."], "answer": "B"}, {"n": 11, "q": "What is on at the cathedral?", "options": ["music", "poetry", "films"], "answer": "A"}, {"n": 12, "q": "What does the festival programme offer at Ickworth?", "options": ["a walk and a book reading", "a concert and a meal", "a walk and a concert"], "answer": "C"}, {"n": 13, "q": "You can’t use a credit card if you book", "options": ["by post.", "by fax.", "by telephone."], "answer": "A"}]}, {"part": 3, "intro": "You will hear someone talking on the radio about a Language Study Fair.", "audio": "audio/pet2-t2-l3.mp3", "notes": "The Language Study Fair\n\nDates: 17th to 19th [14]\nPlace: National Education Centre\nFair includes:\n• stands with textbooks\n• [15] by educational speakers\n• exhibition of furniture\n• demonstrations of latest [16]\nOpening hours: 9.30 a.m.–5.00 p.m. Thursday and Friday\n9.30 a.m.–4.00 p.m. [17]\nTickets: £5\nor £3 for [18]\nTickets can be booked by ringing the hotline on [19]", "answers": {"14": ["of March", "March"], "15": ["talk", "talks"], "16": ["computer programs", "computer program", "computer programmes", "computer programme"], "17": ["Saturday"], "18": ["full-time students", "full-time student", "students", "student", "full time students", "full time student", "fulltime students", "fulltime student", "time students", "time student"], "19": ["984 7711", "9847711"]}}, {"part": 4, "intro": "You will hear a conversation between a girl, Kate, and a boy, George.", "audio": "audio/pet2-t2-l4.mp3", "items": [{"n": 20, "q": "Kate has stopped taking her medicine.", "answer": "B"}, {"n": 21, "q": "George thinks Kate should stay away from class.", "answer": "A"}, {"n": 22, "q": "Kate had an accident on her bike last week.", "answer": "B"}, {"n": 23, "q": "George thinks Mr Gray is a lazy lecturer.", "answer": "A"}, {"n": 24, "q": "Kate will miss three lectures.", "answer": "A"}, {"n": 25, "q": "Kate wants to stay at home at the weekend.", "answer": "B"}]}]};
